// AP_Camera::change_setting
static __attribute__((noinline)) int32_t binding_102(const uint8_t *input, uint32_t input_size,
                                                       uint8_t *output, uint32_t output_size)
{
    if (input_size != 9 || output_size != 1 ||
        (input_size != 0 && input == nullptr) || (output_size != 0 && output == nullptr)) {
        return AP_RUST_STATUS_INVALID;
    }
    memset(output, 0, 1);
#if (AP_CAMERA_ENABLED && (AP_CAMERA_SCRIPTING_ENABLED == 1))
    auto *ud = AP_Camera::get_singleton();
    if (ud == nullptr) {
        return AP_RUST_STATUS_UNAVAILABLE;
    }
    const uint8_t arg0 = uint8_t(BindingWire::read(input + 0, 1));
    const uint32_t bits1 = uint32_t(BindingWire::read(input + 1, 4));
    int32_t arg1;
    memcpy(&arg1, &bits1, sizeof(arg1));
    if (!BindingWire::valid_enum<CameraSetting>(arg1)) {
        return AP_RUST_STATUS_INVALID;
    }
    if (!BindingWire::in_range<int64_t>(arg1, (static_cast<int32_t>(CameraSetting::THERMAL_PALETTE)), (static_cast<int32_t>(CameraSetting::THERMAL_RAW_DATA)))) {
        return AP_RUST_STATUS_INVALID;
    }
    const float arg2 = BindingWire::read_float(input + 5);
    BindingLock lock(ud->get_semaphore());
    if (!lock.taken()) {
        return AP_RUST_STATUS_BUSY;
    }
    const auto value = ud->change_setting(arg0, static_cast<CameraSetting>(arg1), arg2);
    BindingWire::write(output + 0, uint32_t(value), 1);
    return AP_RUST_STATUS_OK;
#else
    return AP_RUST_STATUS_UNAVAILABLE;
#endif
}

