// AP_Mission::get_item
static __attribute__((noinline)) int32_t binding_165(const uint8_t *input, uint32_t input_size,
                                                       uint8_t *output, uint32_t output_size)
{
    if (input_size != 2 || output_size != 39 ||
        (input_size != 0 && input == nullptr) || (output_size != 0 && output == nullptr)) {
        return AP_RUST_STATUS_INVALID;
    }
    memset(output, 0, 39);
#if (AP_MISSION_ENABLED)
    auto *ud = AP_Mission::get_singleton();
    if (ud == nullptr) {
        return AP_RUST_STATUS_UNAVAILABLE;
    }
    const uint16_t arg0 = uint16_t(BindingWire::read(input + 0, 2));
    mavlink_mission_item_int_t arg1{};
#if AP_SCHEDULER_ENABLED
    auto *scheduler = AP_Scheduler::get_singleton();
    if (scheduler == nullptr) {
        return AP_RUST_STATUS_UNAVAILABLE;
    }
    BindingLock lock(scheduler->get_semaphore());
    if (!lock.taken()) {
        return AP_RUST_STATUS_BUSY;
    }
#endif
    const auto value = ud->get_item(arg0, arg1);
    output[0] = value ? 1 : 0;
    if (value) {
        BindingWire::write_float(output + 1, arg1.param1);
        BindingWire::write_float(output + 5, arg1.param2);
        BindingWire::write_float(output + 9, arg1.param3);
        BindingWire::write_float(output + 13, arg1.param4);
        BindingWire::write(output + 17, uint32_t(arg1.x), 4);
        BindingWire::write(output + 21, uint32_t(arg1.y), 4);
        BindingWire::write_float(output + 25, arg1.z);
        BindingWire::write(output + 29, uint32_t(arg1.seq), 2);
        BindingWire::write(output + 31, uint32_t(arg1.command), 2);
        BindingWire::write(output + 33, uint32_t(arg1.target_system), 1);
        BindingWire::write(output + 34, uint32_t(arg1.target_component), 1);
        BindingWire::write(output + 35, uint32_t(arg1.frame), 1);
        BindingWire::write(output + 36, uint32_t(arg1.current), 1);
        BindingWire::write(output + 37, uint32_t(arg1.autocontinue), 1);
        BindingWire::write(output + 38, uint32_t(arg1.mission_type), 1);
    }
    return AP_RUST_STATUS_OK;
#else
    return AP_RUST_STATUS_UNAVAILABLE;
#endif
}

