    Location arg1{};
    if (!read_value_Location(input + 1, arg1)) {
        return AP_RUST_STATUS_INVALID;
    }
    Quaternion arg2{};
    if (!read_value_Quaternion(input + 18, arg2)) {
        return AP_RUST_STATUS_INVALID;
    }
    Vector3f arg3{};
    if (!read_value_Vector3f(input + 34, arg3)) {
        return AP_RUST_STATUS_INVALID;
    }
    Vector3f arg4{};
    if (!read_value_Vector3f(input + 46, arg4)) {
        return AP_RUST_STATUS_INVALID;
    }
    const auto value = ud->set_pose(arg0, arg1, arg2, arg3, arg4);
    BindingWire::write(output + 0, uint32_t(value), 1);
    BindingWire::write(output + 1, uint32_t(arg1.relative_alt), 1);
    BindingWire::write(output + 2, uint32_t(arg1.loiter_ccw), 1);
    BindingWire::write(output + 3, uint32_t(arg1.terrain_alt), 1);
    BindingWire::write(output + 4, uint32_t(arg1.origin_alt), 1);
    BindingWire::write(output + 5, uint32_t(arg1.loiter_xtrack), 1);
    BindingWire::write(output + 6, uint32_t(arg1.alt), 4);
    BindingWire::write(output + 10, uint32_t(arg1.lat), 4);
    BindingWire::write(output + 14, uint32_t(arg1.lng), 4);
    BindingWire::write_float(output + 18, arg2.q1);
    BindingWire::write_float(output + 22, arg2.q2);
    BindingWire::write_float(output + 26, arg2.q3);
    BindingWire::write_float(output + 30, arg2.q4);
    BindingWire::write_float(output + 34, arg3.x);
    BindingWire::write_float(output + 38, arg3.y);
    BindingWire::write_float(output + 42, arg3.z);
    BindingWire::write_float(output + 46, arg4.x);
    BindingWire::write_float(output + 50, arg4.y);
    BindingWire::write_float(output + 54, arg4.z);
    return AP_RUST_STATUS_OK;
