// RC_Channel::get_aux_switch_pos
static __attribute__((noinline)) int32_t binding_348(const uint8_t *input, uint32_t input_size,
                                                       uint8_t *output, uint32_t output_size)
{
    if (input_size != 4 || output_size != 1 ||
        (input_size != 0 && input == nullptr) || (output_size != 0 && output == nullptr)) {
        return AP_RUST_STATUS_INVALID;
    }
    memset(output, 0, 1);
#if (AP_RC_CHANNEL_ENABLED)
    const uint32_t token = BindingWire::read(input, 4);
    if (token < 1 || token - 1 >= NUM_RC_CHANNELS) {
        return AP_RUST_STATUS_INVALID;
    }
#if AP_SCHEDULER_ENABLED
    auto *scheduler = AP_Scheduler::get_singleton();
    if (scheduler == nullptr) {
        return AP_RUST_STATUS_UNAVAILABLE;
    }
    BindingLock lock(scheduler->get_semaphore());
    if (!lock.taken()) {
        return AP_RUST_STATUS_BUSY;
    }
#endif
    auto *owner = RC_Channels::get_singleton();
    if (owner == nullptr) {
        return AP_RUST_STATUS_UNAVAILABLE;
    }
    auto *ud = owner->channel(token - 1);
    if (ud == nullptr) {
        return AP_RUST_STATUS_UNAVAILABLE;
    }
    const auto value = ud->get_aux_switch_pos();
    BindingWire::write(output + 0, uint32_t(value), 1);
    return AP_RUST_STATUS_OK;
#else
    return AP_RUST_STATUS_UNAVAILABLE;
#endif
}

